#!/usr/bin/env python3
"""Generate 200 premium Neuroscience Q&A pairs -- Upgrade L"""
import json, pathlib

OUT = pathlib.Path('/workspace/data_upgrades')
OUT.parent.mkdir(parents=True, exist_ok=True)

pairs = [
    ("What is neuroscience?", "Neuroscience is the scientific study of the nervous system -- its structure, function, development, genetics, biochemistry, physiology, pharmacology, and pathology. It spans from molecular mechanisms at synapses to systems-level cognition and behaviour. Subdisciplines include cellular, systems, cognitive, computational, and clinical neuroscience."),
    ("What is a neuron?", "A neuron is the fundamental signalling unit of the nervous system. It consists of a cell body (soma) containing the nucleus; dendrites that receive inputs; an axon that conducts action potentials away from the soma; and axon terminals that release neurotransmitters at synapses. The human brain contains roughly 86 billion neurons forming trillions of synaptic connections."),
    ("What is the resting membrane potential?", "The resting membrane potential (~-70 mV, inside negative) arises from the differential distribution of ions maintained by the Na+/K+ ATPase pump (3 Na+ out, 2 K+ in) and selective membrane permeability. At rest, the membrane is most permeable to K+ (via leak channels), which flows out down its concentration gradient, leaving negative charges inside. The equilibrium potential for K+ (~-90 mV) drives the resting potential toward -70 mV."),
    ("What is an action potential?", "An action potential is an all-or-nothing electrical impulse propagated along the axon. Depolarisation to threshold (-55 mV) opens voltage-gated Na+ channels, causing rapid Na+ influx and the spike to +40 mV. Voltage-gated K+ channels then open, repolarising the membrane. A transient hyperpolarisation (afterhyperpolarisation) is followed by return to rest. The refractory period prevents backward propagation."),
    ("What is saltatory conduction?", "In myelinated axons, the action potential jumps between nodes of Ranvier -- gaps in the myelin sheath where Na+ channels are concentrated. This saltatory (jumping) conduction is much faster and more energy-efficient than continuous conduction in unmyelinated fibres. Multiple sclerosis damages myelin, slowing or blocking conduction and causing motor and sensory deficits."),
    ("What is a synapse?", "A synapse is the junction where one neuron communicates with another or with an effector cell. At chemical synapses, an action potential triggers Ca2+ influx at the presynaptic terminal, causing synaptic vesicles to fuse with the membrane and release neurotransmitter into the synaptic cleft. The neurotransmitter diffuses across and binds receptors on the postsynaptic membrane, generating an EPSP or IPSP."),
    ("What is an excitatory postsynaptic potential?", "An EPSP is a graded depolarisation of the postsynaptic membrane caused by neurotransmitter binding (e.g., glutamate activating AMPA receptors), which opens cation channels, allowing Na+ influx. EPSPs summate temporally and spatially at the axon hillock; if threshold is reached, an action potential fires. EPSPs are graded -- larger presynaptic volleys produce larger EPSPs."),
    ("What is an inhibitory postsynaptic potential?", "An IPSP is a graded hyperpolarisation (or stabilisation at rest) of the postsynaptic membrane caused by neurotransmitter binding (e.g., GABA activating GABA-A receptors), opening Cl- channels. Cl- influx moves the membrane potential toward ECl (-65 to -70 mV), making it harder to reach threshold. IPSPs counterbalance EPSPs to modulate the likelihood of firing."),
    ("What is glutamate in neuroscience?", "Glutamate is the principal excitatory neurotransmitter in the CNS. It acts on AMPA receptors (fast, Na+ influx), NMDA receptors (slow, Ca2+ influx -- voltage-gated and ligand-gated, requiring depolarisation to relieve Mg2+ block), and metabotropic receptors (G protein-coupled). NMDA receptor activation is critical for synaptic plasticity, learning, and memory. Excess glutamate causes excitotoxicity."),
    ("What is GABA?", "GABA (gamma-aminobutyric acid) is the principal inhibitory neurotransmitter. GABA-A receptors are ligand-gated Cl- channels; GABA-B receptors are G protein-coupled (K+ channels). Benzodiazepines (diazepam) and barbiturates potentiate GABA-A channel opening, producing anxiolytic and sedative effects. GABA interneurons regulate circuit excitability and prevent runaway excitation. GABA dysregulation is implicated in epilepsy and anxiety."),
    ("What is dopamine?", "Dopamine is a catecholamine neurotransmitter with multiple CNS functions. Mesolimbic pathway (VTA to nucleus accumbens): reward, motivation, and addiction. Mesocortical pathway (VTA to PFC): cognition and executive function. Nigrostriatal pathway (substantia nigra to striatum): motor control -- depleted in Parkinson's disease. Tuberoinfundibular pathway: regulates prolactin. D1 and D2 receptors mediate opposing effects on adenylyl cyclase."),
    ("What is serotonin?", "Serotonin (5-hydroxytryptamine, 5-HT) is a monoamine neurotransmitter synthesised from tryptophan. Raphe nuclei project widely to the forebrain, modulating mood, sleep, appetite, cognition, and social behaviour. SSRIs (fluoxetine) block serotonin reuptake, elevating synaptic levels and treating depression and anxiety. 5-HT2A receptor agonism mediates psychedelic effects of psilocybin and LSD."),
    ("What is norepinephrine?", "Norepinephrine (noradrenaline) is a catecholamine from locus coeruleus neurons that project broadly to the forebrain. It regulates arousal, attention, the stress response (fight-or-flight), and mood. Alpha and beta adrenergic receptors mediate its effects. SNRIs and TCAs increase NE availability. Beta-blockers block adrenergic receptors, reducing anxiety symptoms. NE dysregulation contributes to depression, PTSD, and ADHD."),
    ("What is acetylcholine?", "Acetylcholine (ACh) acts at neuromuscular junctions (nicotinic receptors -- ligand-gated ion channels) and in the ANS (both nicotinic and muscarinic receptors). In the CNS, basal forebrain cholinergic neurons project to cortex and hippocampus, modulating attention, memory consolidation, and REM sleep. Acetylcholinesterase inhibitors (donepezil) slow the breakdown of ACh, modestly improving cognition in Alzheimer's disease."),
    ("What is long-term potentiation?", "LTP is a long-lasting strengthening of synaptic efficacy following high-frequency stimulation, believed to underlie learning and memory. At Schaffer collateral-CA1 synapses, repetitive glutamate release activates AMPA receptors (depolarising the cell) and NMDA receptors (opened by depolarisation removing Mg2+ block), allowing Ca2+ influx. Ca2+ activates CaMKII and other kinases, phosphorylating and inserting more AMPA receptors -- increasing synaptic strength."),
    ("What is Hebb's rule?", "Hebb's postulate (1949): 'neurons that fire together, wire together.' When a presynaptic neuron repeatedly activates a postsynaptic neuron, the synaptic connection strengthens. LTP is the physiological mechanism implementing Hebb's rule -- NMDA receptors act as coincidence detectors requiring simultaneous pre- and postsynaptic activity. Anti-Hebbian plasticity (spike-timing-dependent plasticity, STDP) strengthens or weakens synapses based on the precise timing of pre- and postsynaptic spikes."),
    ("What is long-term depression?", "LTD is the persistent weakening of synaptic strength following low-frequency stimulation or anti-correlated pre- and postsynaptic activity. At climbing fibre-Purkinje cell synapses in the cerebellum, conjunctive activation of parallel fibres and climbing fibres triggers PKC-mediated internalisation of AMPA receptors. LTD in the cerebellum mediates motor learning. In the hippocampus, homosynaptic LTD can coexist with LTP."),
    ("What is neuroplasticity?", "Neuroplasticity is the brain's capacity to reorganise neural connections in response to experience, learning, or injury. Forms: synaptic plasticity (LTP/LTD), structural plasticity (changes in dendritic spine density and morphology), adult neurogenesis (new neurons in hippocampal dentate gyrus and olfactory bulb), and large-scale cortical map reorganisation after peripheral injury or extensive training."),
    ("What is adult neurogenesis?", "New neurons are generated throughout life in the hippocampal dentate gyrus (from neural stem cells) and the olfactory bulb (from the subventricular zone). Neurogenesis is increased by exercise and enriched environments and decreased by stress and aging. New hippocampal neurons integrate into circuits within weeks and are thought to contribute to pattern separation, contextual learning, and clearance of old memories."),
    ("What is the cortical map?", "The cortical map is the topographic representation of the body (somatotopy) or sensory space (retinotopy, tonotopy) across the cortex. The somatosensory homunculus shows areas proportional to innervation density (hands and lips are large). Cortical maps are plastic -- amputation of a finger causes neighbouring representations to expand; Braille readers show enlarged hand representations. Hebbian plasticity drives map reorganisation with use."),
    ("What is the structure of the cerebral cortex?", "The cerebral cortex is ~3 mm thick, folded into gyri (ridges) and sulci (grooves) to maximise surface area within the skull. It contains six layers (I-VI) with distinct cell types and connectivity patterns. Layer IV receives thalamic input; Layer V sends long-range projections to subcortical structures; Layer VI projects back to the thalamus. The cortex is divided into frontal, parietal, temporal, and occipital lobes."),
    ("What is the limbic system?", "The limbic system comprises interconnected structures mediating emotion, memory, motivation, and olfaction: hippocampus (declarative memory, spatial navigation), amygdala (fear and emotional learning), hypothalamus (autonomic and endocrine regulation), cingulate cortex (error monitoring, pain), and septal nuclei. The Papez circuit (hippocampus-cingulate-mammillary bodies-thalamus) was originally described as the circuit of emotion."),
    ("What is the amygdala?", "The amygdala (Greek: almond) is a medial temporal lobe structure critical for emotional processing, particularly fear. The basolateral amygdala (BLA) receives multimodal sensory input and mediates fear conditioning -- associating a neutral CS with an aversive US. The central nucleus mediates fear expression (freezing, autonomic responses). The amygdala modulates memory consolidation in the hippocampus via noradrenaline."),
    ("What is the hippocampus?", "The hippocampus is a medial temporal lobe structure essential for forming new declarative memories (episodic and semantic) and spatial navigation. The trisynaptic circuit (entorhinal cortex to dentate gyrus via perforant path; dentate gyrus to CA3 via mossy fibres; CA3 to CA1 via Schaffer collaterals) is the canonical memory circuit. Place cells encode spatial location; grid cells in entorhinal cortex provide a metric for navigation."),
    ("What is the basal ganglia?", "The basal ganglia are subcortical nuclei involved in motor control, habit learning, reward-based decision-making, and action selection. Structures: caudate nucleus and putamen (striatum -- input); globus pallidus and substantia nigra pars reticulata (output); subthalamic nucleus; substantia nigra pars compacta (dopamine source). The direct pathway facilitates movement; the indirect pathway suppresses it. Loss of dopaminergic neurons causes Parkinson's disease."),
    ("What is the cerebellum?", "The cerebellum ('little brain') contains more neurons than the rest of the brain combined. It coordinates movement timing, precision, and fine motor learning. Purkinje cells are the sole output of the cerebellar cortex (inhibitory, projecting to deep nuclei). Climbing fibres from the inferior olive signal error; parallel fibres from granule cells provide context. Cerebellar lesions cause ataxia, dysmetria, and impaired motor learning."),
    ("What is the thalamus?", "The thalamus is the brain's relay station -- a paired structure of nuclei that relays sensory (except olfaction) and motor information to the cortex and receives massive reciprocal projections. Specific relay nuclei (LGN for vision, MGN for audition, VPL for somatosensation) project to primary cortical areas. The pulvinar and MD nuclei connect to association cortex and PFC. The thalamus also regulates consciousness and arousal (intralaminar nuclei)."),
    ("What is the hypothalamus?", "The hypothalamus regulates homeostasis, neuroendocrine function, and autonomic output. Nuclei control: feeding (arcuate nucleus -- NPY/AgRP vs POMC/CART neurons); thermoregulation; circadian rhythm (suprachiasmatic nucleus -- master clock); reproductive behaviour (GnRH neurons); stress response (paraventricular nucleus -- CRH); sleep-wake (lateral hypothalamus -- orexin/hypocretin); and fluid balance (vasopressin release)."),
    ("What is the autonomic nervous system?", "The ANS regulates involuntary functions: heart rate, blood pressure, digestion, and glandular secretion. The sympathetic division (fight-or-flight) uses noradrenaline at effectors and arises from thoracolumbar spinal cord. The parasympathetic division (rest-and-digest) uses acetylcholine and arises from the brainstem and sacral cord. The enteric nervous system (gut's own nervous system) is often considered a third division."),
    ("What is the default mode network?", "The DMN is a set of brain regions most active during rest, self-referential thought, mind-wandering, social cognition, and episodic memory retrieval: medial PFC, posterior cingulate cortex, angular gyrus, and medial temporal lobe. It deactivates during externally directed attention. DMN dysfunction is associated with depression (rumination), schizophrenia (disordered self-narrative), Alzheimer's disease (DMN hubs accumulate amyloid early), and autism."),
    ("What is the prefrontal cortex?", "The PFC is the anterior part of the frontal lobe, supporting executive function: working memory, planning, decision-making, cognitive flexibility, response inhibition, and social behaviour. The dlPFC supports working memory and top-down attention. The vmPFC integrates emotional valuation with decision-making (Damasio's somatic marker). The OFC encodes reward value. The ACC monitors conflict and error. PFC matures into the mid-20s -- explaining adolescent impulsivity."),
    ("What is the visual cortex?", "Primary visual cortex (V1, striate cortex) in the occipital lobe receives input from the LGN and is retinotopically mapped. Simple cells respond to oriented edges; complex cells respond to orientation across positions; hypercomplex cells respond to length. The dorsal ('where/how') stream projects to parietal cortex for spatial vision and action; the ventral ('what') stream projects to temporal cortex for object recognition (fusiform face area, parahippocampal place area)."),
    ("What is the auditory cortex?", "Primary auditory cortex (A1) in the superior temporal plane (Heschl's gyrus) is tonotopically organised -- neurons respond best to specific sound frequencies, arranged from low to high. It processes sound features: frequency, intensity, duration, and temporal patterns. Core areas project to belt and parabelt regions for increasingly complex processing. Left hemisphere is dominant for speech; right for prosody and music."),
    ("What is the motor cortex?", "Primary motor cortex (M1, precentral gyrus) contains corticospinal neurons (Betz cells in Layer V) that project via the pyramidal tract to spinal motor neurons controlling voluntary movement. The motor homunculus maps the body somatotopically, with hands and face occupying disproportionate areas. Premotor cortex and supplementary motor area plan and programme sequences. Lesions cause contralateral weakness or paralysis (upper motor neuron signs)."),
    ("What is Broca's area?", "Broca's area (inferior frontal gyrus, BA44/45 in the dominant hemisphere) is critical for speech production and syntactic processing. Damage causes Broca's (expressive) aphasia -- halting, effortful speech with preserved comprehension but impaired grammar. It is part of a broader left-hemisphere language network. Broca's area also activates during action observation (mirror neurons) and understanding action-related language."),
    ("What is Wernicke's area?", "Wernicke's area (posterior superior temporal gyrus, BA22, dominant hemisphere) processes speech comprehension. Damage causes Wernicke's (receptive) aphasia -- fluent but nonsensical speech (jargon aphasia) with impaired comprehension. The arcuate fasciculus connects Broca's and Wernicke's areas; damage causes conduction aphasia (impaired repetition with preserved production and comprehension). Language is organised in a network, not just two centres."),
    ("What is the mirror neuron system?", "Mirror neurons (first discovered in macaque F5 area) fire both when an action is performed and when the same action is observed in others. Proposed functions: action understanding, imitation, and theory of mind. In humans, the putative mirror system includes inferior frontal gyrus and inferior parietal lobule. The system is implicated in autism (broken mirror hypothesis -- controversial) and social cognition."),
    ("What is the reticular activating system?", "The ascending reticular activating system (ARAS) is a network of brainstem nuclei (locus coeruleus, raphe nuclei, pedunculopontine tegmentum, basal forebrain) projecting broadly to the thalamus and cortex, releasing neuromodulators (NE, 5-HT, ACh, histamine). It maintains arousal and wakefulness. Damage causes coma; general anaesthesia suppresses it. The thalamus gates sensory information to the cortex based on ARAS activity."),
    ("What is the electroencephalogram?", "The EEG records summed postsynaptic potentials from millions of cortical neurons via scalp electrodes. Characteristic oscillations: delta (0.5-4 Hz, deep sleep); theta (4-8 Hz, hippocampal navigation, drowsiness); alpha (8-13 Hz, relaxed wakefulness, eyes closed); beta (13-30 Hz, active cognition); gamma (30-80 Hz+, local synchrony, sensory processing). Event-related potentials (ERPs -- e.g., P300, N400) reflect cognitive processing with millisecond resolution."),
    ("What is functional MRI?", "fMRI measures the BOLD (Blood Oxygen Level Dependent) signal -- the ratio of oxygenated to deoxygenated haemoglobin, which changes with neural activity due to neurovascular coupling. Spatial resolution is 1-3 mm; temporal resolution is seconds (haemodynamic response peaks at 4-6 s). fMRI maps brain activity during tasks, identifies networks (ICA-based resting-state), and guides neurosurgical planning. Limitations: indirect measure, susceptibility artefacts, and modest signal-to-noise."),
    ("What is diffusion tensor imaging?", "DTI maps white matter tractography by measuring the directional diffusion of water molecules -- diffusion is anisotropic in myelinated fibre bundles. It reveals major white matter tracts (corticospinal, arcuate fasciculus, cingulum, uncinate fasciculus) and their microstructural integrity (fractional anisotropy). DTI is used to study connectivity, white matter lesions in MS and TBI, and neurodevelopmental trajectories."),
    ("What is the connectome?", "The connectome is the comprehensive map of neural connections in the nervous system. The C. elegans connectome (302 neurons, 7,000 synapses) was the first fully mapped. Human macroscale connectome (Human Connectome Project) uses DTI and fMRI to map white matter tracts and functional networks. Individual differences in connectome organisation predict cognitive abilities, psychiatric risk, and personality traits."),
    ("What is the blood-brain barrier?", "The BBB is a selective permeability barrier formed by tight junctions between brain capillary endothelial cells, supported by pericytes and astrocyte endfeet. It excludes large molecules, hydrophilic compounds, and most drugs, maintaining a stable CNS microenvironment. Lipophilic molecules cross freely; essential nutrients use specific transporters (glucose via GLUT1). Dysfunction of the BBB contributes to neuroinflammation, Alzheimer's disease, and tumour oedema."),
    ("What is neuroinflammation?", "Neuroinflammation is the activation of CNS immune cells -- microglia (resident macrophages) and astrocytes -- in response to injury, infection, or disease. Acute neuroinflammation is protective (clearing debris, limiting damage). Chronic neuroinflammation contributes to neurodegenerative diseases (Alzheimer's, Parkinson's, ALS), depression, and traumatic brain injury. Microglia survey the brain continuously with motile processes; pathological activation causes cytokine release and synaptic pruning."),
    ("What are microglia?", "Microglia are the resident immune cells of the CNS, derived from yolk-sac progenitors. In the healthy brain they survey the microenvironment, phagocytose apoptotic cells and synaptic debris, and regulate synaptic plasticity (synaptic pruning via complement). Activated microglia adopt phagocytic or pro-inflammatory phenotypes. Excessive microglial pruning during development is implicated in schizophrenia; dysregulated microglial activation drives neurodegeneration."),
    ("What is astrocyte function?", "Astrocytes (the most numerous CNS cells) maintain homeostasis: regulating extracellular K+ and glutamate (via glutamate transporters), forming the BBB, providing metabolic support (lactate shuttle to neurons), guiding axon development, forming the glial scar after injury, and modulating synaptic transmission. Tripartite synapse: astrocytes sense and respond to neurotransmitters, releasing gliotransmitters (ATP, D-serine) that modulate synaptic efficacy."),
    ("What is the tripartite synapse?", "The tripartite synapse concept (Araque et al., 1999) expands the classical two-part synapse to include the perisynaptic astrocytic process as an active participant. Astrocytes sense neurotransmitters (via receptors), respond with intracellular Ca2+ waves, and release gliotransmitters (glutamate, ATP, D-serine) that modulate presynaptic release probability and postsynaptic NMDA receptor function. Astrocytes thus actively participate in synaptic computation."),
    ("What is Alzheimer's disease neuroscience?", "Alzheimer's disease is characterised by accumulation of amyloid-beta (Abeta) plaques (extracellular) and tau neurofibrillary tangles (intracellular hyperphosphorylated tau) leading to synaptic loss and neurodegeneration. The amyloid cascade hypothesis holds that Abeta accumulation triggers tau pathology and neurodegeneration. Early changes occur in the entorhinal cortex and hippocampus, explaining early memory deficits. Anti-amyloid antibodies (lecanemab) slow disease progression modestly."),
    ("What is Parkinson's disease neuroscience?", "Parkinson's disease involves progressive loss of dopaminergic neurons in the substantia nigra pars compacta, causing striatal dopamine depletion and motor symptoms (tremor at rest, rigidity, bradykinesia, postural instability). Lewy bodies (alpha-synuclein aggregates) are the pathological hallmark. Levodopa (dopamine precursor) remains the mainstay of treatment. Deep brain stimulation of the subthalamic nucleus or GPi effectively controls motor symptoms."),
    ("What is the dopamine prediction error signal?", "Midbrain dopamine neurons (VTA and substantia nigra) encode a reward prediction error (RPE) signal: they fire phasically when an unexpected reward occurs (positive RPE), are suppressed when an expected reward is omitted (negative RPE), and are unresponsive to fully predicted rewards. This signal matches the Rescorla-Wagner model of associative learning and the temporal difference learning algorithm in reinforcement learning."),
    ("What is the hypothalamic-pituitary-adrenal axis?", "The HPA axis mediates the stress response: the paraventricular nucleus of the hypothalamus releases CRH, which stimulates ACTH release from the anterior pituitary, triggering cortisol secretion from the adrenal cortex. Cortisol mobilises energy, suppresses inflammation, and provides negative feedback to the hypothalamus and pituitary. Chronic stress dysregulates the HPA axis, causing hippocampal atrophy, impaired immunity, and depression risk."),
    ("What is oxytocin?", "Oxytocin is a neuropeptide synthesised in the hypothalamus (paraventricular and supraoptic nuclei) and released from the posterior pituitary. Peripheral functions: uterine contraction during labour, milk ejection. CNS functions: social bonding, trust, empathy, anxiety reduction, and maternal behaviour. It acts on widespread forebrain OT receptors. Intranasal oxytocin increases trust in economic games (Zak) and is being studied for autism and social anxiety."),
    ("What is vasopressin?", "Vasopressin (antidiuretic hormone, ADH) is synthesised in the hypothalamus and released from the posterior pituitary. It acts on renal V2 receptors to increase water reabsorption (antidiuresis) and on V1 receptors to cause vasoconstriction. In the brain, vasopressin regulates social behaviour, aggression, and pair bonding (critical in monogamous prairie voles). SIADH (inappropriate ADH secretion) causes dilutional hyponatraemia."),
    ("What is the circadian rhythm?", "Circadian rhythms are self-sustaining ~24-hour cycles driven by the molecular clock in the suprachiasmatic nucleus (SCN) of the hypothalamus. The core clock genes (CLOCK, BMAL1, PER1/2, CRY1/2) form a transcription-translation feedback loop with a period of ~24 hours. Light entrains the clock via retinohypothalamic tract projections to the SCN. The clock regulates sleep-wake cycles, hormone secretion, metabolism, and immune function."),
    ("What is the molecular clock mechanism?", "CLOCK and BMAL1 proteins form a heterodimer that drives transcription of PER and CRY genes. PER and CRY proteins accumulate, form a complex, and inhibit CLOCK-BMAL1, repressing their own transcription. As PER/CRY are degraded (phosphorylated by CKIepsilon), repression is relieved and the cycle repeats (~24 hours). Post-translational modifications (phosphorylation, ubiquitination) fine-tune period length. Mutations in clock genes cause familial advanced sleep phase syndrome."),
    ("What is sleep and its neural control?", "Sleep is controlled by two processes: the circadian clock (Process C -- SCN) and homeostatic pressure (Process S -- adenosine accumulation). NREM sleep is generated by thalamo-cortical circuits (sleep spindles from thalamic reticular nucleus, delta waves from cortical networks). REM sleep is generated by brainstem circuits (PPT cholinergic neurons activated, LC and raphe suppressed -- REM-off). The VLPO hypothalamic nucleus promotes sleep by inhibiting arousal systems."),
    ("What is the function of sleep for the brain?", "Sleep serves multiple brain functions: synaptic homeostasis (synaptic downscaling during NREM -- Tononi and Cirelli); memory consolidation (replay of hippocampal sequences during slow-wave sleep and theta oscillations during REM); metabolic waste clearance (glymphatic system -- CSF flushes interstitial space during NREM, clearing amyloid and tau); emotional processing (REM sleep reduces amygdala reactivity to aversive stimuli -- Walker); and immune function."),
    ("What is the glymphatic system?", "The glymphatic system (Nedergaard) is a brain-wide waste clearance pathway using CSF and the perivascular space. During sleep, aquaporin-4 (AQP4) channels on astrocyte endfeet facilitate CSF influx alongside arteries, washing through brain parenchyma and effluxing along veins, clearing interstitial waste (amyloid-beta, tau, lactate). Glymphatic flow is reduced during wakefulness and by sleep deprivation, linking insufficient sleep to Alzheimer's risk."),
    ("What is the neural basis of pain?", "Nociceptors (free nerve endings, C-fibres and A-delta fibres) transduce noxious stimuli (thermal, mechanical, chemical) and transmit signals to the dorsal horn of the spinal cord, where they synapse onto projection neurons in the spinothalamic tract (transmitting to thalamus and cortex). Gate control theory (Melzack and Wall): large-fibre input inhibits nociceptive transmission via interneurons. Descending modulation from PAG and RVM amplifies or suppresses pain."),
    ("What is the periaqueductal grey?", "The PAG (periaqueductal grey) surrounds the cerebral aqueduct in the midbrain and is a major hub for pain modulation, fear responses, and defensive behaviour. The PAG integrates inputs from the amygdala, hypothalamus, and prefrontal cortex and drives descending modulation of spinal nociception (via the RVM). It mediates opioid analgesia -- injecting morphine into the PAG produces profound analgesia. It also organises fight, flight, and freeze behaviours."),
    ("What are endogenous opioids?", "Endogenous opioids (endorphins, enkephalins, dynorphins) are neuropeptides that activate mu, delta, and kappa opioid receptors to modulate pain, mood, reward, and stress. Beta-endorphin from the arcuate nucleus activates mu receptors in the PAG and limbic system. Exercise-induced euphoria ('runner's high') involves endocannabinoids (and possibly endorphins). Opioid receptors are widely distributed; all opioid drugs act on these endogenous systems."),
    ("What is the endocannabinoid system?", "Endocannabinoids (anandamide, 2-AG) are lipid-derived retrograde messengers synthesised on demand from postsynaptic membranes, acting on presynaptic CB1 receptors to suppress neurotransmitter release. They mediate short-term synaptic depression (DSI/DSE), modulate pain, appetite, mood, memory, and neuroprotection. THC (cannabis) acts on CB1 receptors. CB1 receptors are among the most abundant GPCRs in the brain; high concentrations in basal ganglia, hippocampus, and cerebellum."),
    ("What is the nucleus accumbens?", "The nucleus accumbens (NAc) is the ventral striatum's core and shell -- the central hub of the brain's reward circuit. Dopaminergic input from VTA modulates glutamatergic inputs from PFC, hippocampus, amygdala, and thalamus to regulate reward salience, motivation, and habit formation. Optogenetic activation of NAc D1-MSNs promotes reward; D2-MSN activation suppresses it. The NAc mediates the rewarding effects of natural rewards and addictive drugs."),
    ("What is addiction neuroscience?", "Addiction involves three stages (Koob and Volkow): bingeing/intoxication (VTA-NAc dopamine release), withdrawal/negative affect (reduced reward function, increased CRH and dynorphin stress systems), and preoccupation/anticipation (PFC-driven craving, loss of inhibitory control). Repeated drug exposure causes synaptic plasticity (LTP at VTA inputs to NAc, AMPA receptor changes), making the addicted circuit hijacked by drug cues and resistant to extinction."),
    ("What is DeltaFosB?", "DeltaFosB is a transcription factor that accumulates in the nucleus accumbens and other brain regions with repeated exposure to drugs of abuse, stress, or natural rewards (exercise, food). It has a longer half-life than other Fos proteins and persists for weeks after drug exposure. DeltaFosB drives gene expression changes (including increased GluA2 AMPA receptor subunits, CDK5) that contribute to long-lasting synaptic adaptations underlying addiction and sensitisation."),
    ("What is optogenetics?", "Optogenetics uses light-sensitive proteins (channelrhodopsin-2 -- ChR2 activates neurons with blue light; halorhodopsin -- NpHR inhibits neurons with yellow light) expressed in specific neurons via viral vectors. Light delivered through fibre optics allows millisecond-precision activation or silencing of defined neuron populations in freely behaving animals. It has revolutionised neuroscience by establishing causal relationships between neural activity and behaviour."),
    ("What is CRISPR in neuroscience?", "CRISPR-Cas9 allows precise editing of genomic DNA in neurons and glia. Applications in neuroscience: creating disease models (Alzheimer's, Parkinson's, Huntington's); correcting disease-causing mutations in patient-derived iPSC-neurons; screening for genes regulating synaptic function; and therapeutic approaches (e.g., correcting the SOD1 mutation in ALS). In vivo CRISPR delivery to the CNS uses AAV vectors; challenges include size, specificity, and off-target effects."),
    ("What is chemogenetics (DREADDs)?", "Designer Receptors Exclusively Activated by Designer Drugs (DREADDs) use engineered muscarinic receptors (hM3Dq -- excitatory; hM4Di -- inhibitory) that are activated by clozapine-N-oxide (CNO) or deschloroclozapine, with no response to endogenous ligands. Expressed via viral vectors in defined cell types, DREADDs allow selective, pharmacologically-controlled activation or silencing of neural circuits in vivo -- complementary to optogenetics (slower kinetics, greater brain penetration)."),
    ("What is the gut-brain axis?", "The gut-brain axis is bidirectional communication between the enteric nervous system (ENS), gut microbiome, and CNS via: the vagus nerve (80% afferent -- ascending gut signals); blood-borne factors (microbiome-derived metabolites, short-chain fatty acids, tryptophan); immune signalling (gut lymphoid tissue); and the HPA axis. The microbiome influences mood, anxiety, and cognition (germ-free mice show anxiety and impaired cognition). Probiotics and faecal transplants are being studied for neuropsychiatric conditions."),
    ("What is the vagus nerve?", "The vagus nerve (cranial nerve X) is the longest cranial nerve, providing parasympathetic innervation to the heart, lungs, and gastrointestinal tract. It is 80% afferent (sensory from viscera to brain) and 20% efferent (motor from brain to viscera). Vagal afferents carry interoceptive signals that influence emotion, memory (via NTS-locus coeruleus-amygdala pathway), and inflammation (the inflammatory reflex). Vagus nerve stimulation (VNS) treats epilepsy and treatment-resistant depression."),
    ("What is interoception?", "Interoception is the sense of the body's internal physiological state -- heartbeat, breathing, temperature, hunger, pain, and visceral sensations. Processed by the insular cortex (particularly the right anterior insula), interoceptive signals inform emotion, motivation, self-awareness, and social cognition. Poor interoceptive accuracy is associated with alexithymia, eating disorders, and autism. Mindfulness meditation improves interoceptive awareness."),
    ("What is the cerebral blood flow regulation?", "Cerebral blood flow is tightly regulated (autoregulation) to maintain constant perfusion across a wide range of blood pressures. Neurovascular coupling: active neurons release vasoactive signals (NO, K+, arachidonic acid metabolites) that dilate local arterioles, increasing blood flow to active regions. Astrocyte endfeet surround arterioles and contribute to neurovascular coupling. Failure of autoregulation contributes to stroke and hypertensive encephalopathy."),
    ("What is ischemic stroke neuroscience?", "Ischaemic stroke (80% of strokes) occurs when a cerebral artery is occluded (thrombosis, embolism). The ischaemic core (no flow) rapidly infarcts due to ATP depletion, Na+/K+ pump failure, membrane depolarisation, Ca2+ influx, and glutamate excitotoxicity. The surrounding penumbra is functionally silent but potentially salvageable by thrombolysis (tPA, <4.5h) or thrombectomy (<24h in selected patients). Reperfusion injury occurs on restoration of blood flow."),
    ("What is excitotoxicity?", "Excitotoxicity (Olney, 1969) is neuronal death caused by excessive glutamate receptor activation. In ischaemia, energy failure causes reversal of glutamate transporters, releasing massive glutamate. NMDA receptor overactivation causes Ca2+ overload, activating calpains, phospholipases, and nitric oxide synthase, leading to mitochondrial failure and apoptosis. Excitotoxicity contributes to ischaemia, epilepsy, ALS, and Huntington's disease."),
    ("What is epilepsy neuroscience?", "Epilepsy involves recurrent seizures -- abnormal, synchronised neuronal discharges. Mechanisms include imbalance of excitation (glutamate) and inhibition (GABA), altered ion channel function, and loss of inhibitory interneurons. Focal seizures arise from a limited cortical region; generalised seizures engage both hemispheres from onset. Anti-epileptic drugs target Na+ channels (carbamazepine), GABA enhancement (benzodiazepines, valproate), or Ca2+ channels. Drug-resistant epilepsy is treated by surgery, VNS, or dietary ketogenic approaches."),
    ("What is traumatic brain injury?", "TBI results from mechanical force causing primary injury (contusion, diffuse axonal injury from shear forces, haemorrhage) and secondary injury (oedema, inflammation, excitotoxicity, ischaemia, ICP elevation). Diffuse axonal injury (DAI) tears white matter tracts at the grey-white junction. Chronic traumatic encephalopathy (CTE) is associated with repeated TBI, characterised by tau pathology and neurodegeneration -- documented in contact sport athletes and military veterans."),
    ("What is multiple sclerosis neuroscience?", "MS is a CNS autoimmune demyelinating disease in which T cells and B cells attack myelin, disrupting saltatory conduction and causing varied neurological symptoms (vision loss, weakness, sensory loss, fatigue, cognitive impairment). Relapsing-remitting MS (RRMS, 85%) alternates relapses and partial recovery. Disease-modifying therapies (interferons, natalizumab, ocrelizumab) reduce relapse rates. Neuroprotection and remyelination remain unmet therapeutic goals."),
    ("What is amyotrophic lateral sclerosis?", "ALS involves progressive degeneration of upper motor neurons (cortex) and lower motor neurons (spinal cord and brainstem), causing ascending paralysis and ultimately respiratory failure. 10% are familial (SOD1, C9orf72, TDP-43 mutations); 90% are sporadic. Glutamate excitotoxicity, mitochondrial dysfunction, and protein aggregation contribute. Riluzole (glutamate antagonist) and edaravone modestly slow progression. SOD1-targeting antisense oligonucleotides show promise."),
    ("What is Huntington's disease neuroscience?", "Huntington's disease is an autosomal dominant neurodegenerative disease caused by expanded CAG repeats (>36) in the HTT gene, encoding polyglutamine-expanded huntingtin protein. Mutant huntingtin aggregates and causes preferential death of striatal medium spiny neurons (indirect pathway) -- causing chorea early and hypokinesia late. Motor, cognitive, and psychiatric symptoms progress over 15-20 years. There is no disease-modifying treatment; huntingtin-lowering therapies are in clinical trials."),
    ("What is Tourette syndrome neuroscience?", "Tourette syndrome involves multiple motor and vocal tics beginning in childhood, driven by dysfunction in the cortico-striato-thalamo-cortical circuits. Reduced GABA interneuron inhibition in the striatum may allow breakthrough activation of thalamo-cortical circuits generating tics. Dopamine (and possibly serotonin and noradrenaline) abnormalities contribute. Treatments target dopamine (haloperidol, aripiprazole), noradrenaline (clonidine), or GABA (benzodiazepines). Comprehensive behavioural intervention for tics (CBIT) is first-line."),
    ("What is consciousness and the neural correlates of consciousness?", "Neural correlates of consciousness (NCCs) are the minimal neural mechanisms jointly sufficient for conscious experience. Posterior cortical hot zone (parietal and occipital areas) is most reliably correlated with conscious content; prefrontal areas are associated with reporting and reflection. Integrated information theory (Tononi -- consciousness = phi, the amount of integrated information) and global workspace theory (Baars -- consciousness = broadcast from workspace to many brain systems) are leading frameworks."),
    ("What is the global workspace theory?", "Baars' global workspace theory: consciousness arises when information is broadcast from a global workspace (a distributed set of neurons in PFC and parietal cortex) to many specialised processors throughout the brain. Non-conscious information is processed locally; conscious information is 'ignited' into the global workspace and made widely available. Dehaene's neuronal global workspace model predicts late (>300 ms) cortical ignition, validated by EEG and intracranial recording."),
    ("What is integrated information theory?", "Tononi's IIT holds that consciousness is identical to integrated information (phi). High-phi systems (human cortex) are highly conscious; systems with low phi (cerebellum -- though neuron-rich, its modular structure has low integration) are not. IIT makes specific predictions: consciousness requires high integration, not just complex processing; the posterior cortical hot zone has higher phi than frontal cortex; and neurological states differ in phi."),
    ("What is attention and its neural basis?", "Selective attention is mediated by a frontoparietal network: the intraparietal sulcus and frontal eye fields for spatial attention, the dorsal anterior cingulate for sustained attention, and the temporoparietal junction for reorienting attention to salient events. Attention enhances sensory representation (increased gain, reduced noise) via top-down modulation of sensory cortex. The pulvinar thalamic nucleus gates sensory information based on attentional demands."),
    ("What is working memory and its neural basis?", "Working memory depends on sustained, recurrent activity in the dlPFC (delay-period firing of neurons encoding the remembered item). Theta (4-8 Hz) oscillations in the hippocampus and PFC organise multiple items in working memory, with item order encoded by theta phase. NMDA receptors and dopamine (D1 receptors in PFC) are critical for maintaining working memory representations. Working memory capacity correlates with intelligence and executive function."),
    ("What is the parietal lobe function?", "The parietal lobe integrates multisensory information for spatial cognition, attention, and action. The posterior parietal cortex (intraparietal sulcus) coordinates visuomotor transformations (reaching and grasping). The angular gyrus (BA39) supports semantic processing, reading, and numerical cognition. The supramarginal gyrus (BA40) is involved in phonological working memory and tool use. Right parietal damage causes hemispatial neglect (ignoring the left side of space)."),
    ("What is hemispatial neglect?", "Hemispatial neglect (typically following right hemisphere damage, especially inferior parietal lobule and temporoparietal junction) is the failure to attend to or respond to stimuli on the contralateral (left) side of space, not explained by primary sensory or motor deficits. Patients bisect lines to the right, omit left-sided items in cancellation tasks, and neglect the left side of imagined scenes. Prism adaptation glasses shift perception and provide lasting neglect improvement."),
    ("What is apoptosis in the nervous system?", "Apoptosis (programmed cell death) is essential for normal brain development -- approximately half of neurons produced are eliminated through apoptosis (neuronal death, Hamburger and Levi-Montalcini). Apoptosis is initiated by withdrawal of neurotrophic factors (NGF, BDNF) signalling through Trk receptors. The intrinsic pathway involves cytochrome c release from mitochondria activating caspase cascades. In disease, pathological apoptosis contributes to neurodegeneration."),
    ("What is nerve growth factor?", "NGF (Levi-Montalcini and Cohen, Nobel 1986) is the founding member of the neurotrophin family. It binds TrkA receptors and p75NTR, promoting survival, differentiation, and axon growth of sympathetic and sensory neurons. NGF and other neurotrophins (BDNF, NT-3, NT-4) are retrogradely transported from target tissues to neuron cell bodies, where they suppress apoptosis (via PI3K-Akt and MAPK pathways). BDNF is critical for hippocampal plasticity, antidepressant effects of exercise, and synapse formation."),
    ("What is BDNF?", "Brain-derived neurotrophic factor (BDNF) acts on TrkB receptors to promote neuronal survival, growth, differentiation, and synaptic plasticity. It is released activity-dependently from neurons and is critical for LTP, memory consolidation, and adult neurogenesis. Exercise elevates hippocampal BDNF, explaining cognitive benefits of physical activity. Antidepressants increase BDNF expression; the BDNF-TrkB pathway is a target for depression and Alzheimer's therapeutics."),
    ("What is the somatosensory system?", "The somatosensory system processes touch, proprioception, vibration, temperature, and pain. Mechanoreceptors (Meissner, Merkel, Pacinian, Ruffini) transduce cutaneous stimuli; signals travel via A-beta fibres to dorsal column nuclei (for touch/proprioception) or via A-delta and C fibres to the dorsal horn (for pain and temperature). The VPL thalamus relays to S1 (primary somatosensory cortex, postcentral gyrus), which is somatotopically organised."),
    ("What is proprioception?", "Proprioception is the sense of body position and movement. Muscle spindles detect muscle length and rate of change (Ia afferents); Golgi tendon organs detect muscle tension (Ib afferents); and joint receptors provide angle information. Proprioceptive signals travel in the dorsal columns (conscious proprioception) and spinocerebellar tracts (unconscious proprioception to cerebellum for motor coordination). Loss of proprioception (large-fibre neuropathy) causes sensory ataxia."),
    ("What is the olfactory system?", "Olfaction is unique in its direct cortical access without thalamic relay. Olfactory receptor neurons (ORNs) in the nasal epithelium express one of ~400 odorant receptor types (humans). Axons project to glomeruli in the olfactory bulb, where mitral cells relay signals to piriform cortex, amygdala, and entorhinal cortex. Olfaction is directly connected to limbic structures, explaining the strong emotional and mnemonic associations of smell. Anosmia is an early symptom of Parkinson's disease and COVID-19."),
    ("What is taste (gustation) neuroscience?", "Taste receptors (type II and III cells in taste buds on papillae) detect five basic qualities: sweet (T1R2/3 receptors), umami (T1R1/3), bitter (T2R family), sour (PKD2L1 channels), and salt (ENaC channels). Signals travel via cranial nerves VII, IX, and X to the nucleus tractus solitarius, then VPM thalamus, to the primary gustatory cortex (anterior insula/frontal operculum). Taste integrates with olfaction, texture, and temperature in the orbitofrontal cortex to generate flavour."),
    ("What is the vestibular system?", "The vestibular system detects head position and motion. Hair cells in the semicircular canals (rotational acceleration) and otolith organs (utricle and saccule -- linear acceleration and gravity) transduce mechanical forces. Signals travel via CN VIII to the vestibular nuclei, which coordinate eye movements (vestibulo-ocular reflex), balance, and spatial orientation. Caloric testing, BPPV repositioning manoeuvres, and electronystagmography assess vestibular function."),
    ("What is the visual pathway?", "Retinal ganglion cells (RGCs) project via the optic nerve to the optic chiasm (nasal fibres cross; temporal fibres do not) to the optic tract, then to the lateral geniculate nucleus (LGN) of the thalamus. LGN projects via the optic radiation (Meyer's loop for inferior visual field in temporal lobe) to primary visual cortex (V1, striate cortex) in the occipital lobe. The pupillary light reflex pathway diverges to the pretectal area and Edinger-Westphal nucleus."),
    ("What is the pupillary light reflex?", "The pupillary light reflex (PLR) constricts the pupil in response to light. Afferent: retinal ipRGCs (intrinsically photosensitive, melanopsin-containing) and classical rods/cones project via CN II to the pretectal area. Efferent: pretectal neurons activate Edinger-Westphal nucleus (CN III), which projects to ciliary ganglion and then to the sphincter pupillae. A relative afferent pupillary defect (RAPD, Marcus Gunn pupil) indicates optic nerve disease on the afferent side."),
    ("What is the electroretinogram?", "The electroretinogram (ERG) is a mass electrical response of the retina to a light stimulus recorded via corneal electrode. The a-wave reflects photoreceptor hyperpolarisation (negative, early); the b-wave reflects bipolar and Muller cell responses (positive, later). Pattern ERG reflects RGC function. ERG identifies retinal disease (retinitis pigmentosa, diabetic retinopathy, CSNB) and is used in pharmaceutical testing of retinal drug toxicity."),
    ("What is colour vision neuroscience?", "Humans have three cone types (L, M, S -- peaking at ~560, 530, 430 nm). Opponent colour processing begins in the retina: midget ganglion cells subtract L from M (red-green), bistratified cells subtract S from L+M (blue-yellow). The LGN parvocellular layers carry colour information; V4 and V8 are cortical colour areas. Dichromacy (red-green colour blindness) results from loss of L or M cones (X-linked); tetrachromacy (four cone types) occurs in some women."),
    ("What is synaptic vesicle exocytosis?", "At chemical synapses, synaptic vesicles (SVs) loaded with neurotransmitter dock at the active zone, primed for release. Ca2+ influx through voltage-gated Ca2+ channels (Cav2.1 and Cav2.2) triggers SNARE complex assembly (synaptobrevin on SV with syntaxin and SNAP-25 on plasma membrane) which draws the membranes together, leading to fusion pore opening and neurotransmitter release. Synaptotagmin is the Ca2+ sensor. Botulinum toxin cleaves SNAREs, blocking release."),
    ("What are SNARE proteins?", "SNARE (Soluble NSF Attachment protein Receptor) proteins mediate membrane fusion. Vesicular SNAREs (v-SNAREs): synaptobrevin/VAMP on synaptic vesicles. Target SNAREs (t-SNAREs): syntaxin and SNAP-25 on the plasma membrane. They form a four-helix bundle that provides the energy to pull the two membranes together. NSF (N-ethylmaleimide-sensitive factor) and alpha-SNAP recycle cis-SNARE complexes. Botulinum and tetanus toxins are zinc proteases that cleave specific SNAREs."),
    ("What is the neural basis of working memory delay activity?", "During the delay period of a working memory task, neurons in the dlPFC maintain sustained firing encoding the remembered item. This persistent activity is generated by recurrent excitation (NMDA receptor-dependent) among PFC neurons. Layer III pyramidal cells with long-range connections are particularly important. Dopamine D1 receptor stimulation in PFC sharpens delay-period firing by reducing noise via inhibitory interneurons. This mechanism may be disrupted in schizophrenia."),
    ("What is predictive coding?", "Predictive coding (Rao and Ballard, Clark, Friston) proposes the brain is a hierarchical prediction machine: higher areas generate predictions about lower-level sensory input; lower areas send prediction errors (mismatch) upward only when predictions are violated. Attention modulates the precision of prediction errors. Mismatch negativity (MMN) in EEG reflects prediction error signalling in auditory cortex. Predictive coding provides a unified framework for perception, attention, learning, and potentially consciousness."),
    ("What is the free energy principle?", "Friston's free energy principle proposes that biological systems minimise a free energy bound on surprise (unexpected sensory input) -- either by updating internal models (perception and learning) or by acting to make the world conform to predictions (active inference). It unifies predictive coding, Bayesian brain theory, and homeostasis. Active inference predicts action as another form of prediction error minimisation -- moving to expected sensory states."),
    ("What is the Bayesian brain hypothesis?", "The Bayesian brain hypothesis proposes that the brain implements Bayesian inference -- combining prior beliefs with likelihood (sensory evidence) to compute posterior beliefs. It explains perception as inference: we perceive the most likely cause of sensory input, not the input itself. Priors can override weak sensory evidence (illusions). Abnormal priors or likelihood weighting may underlie hallucinations (over-weighted priors) and Bayesian accounts of psychiatric disorders are a active research area."),
    ("What is the neural basis of decision-making?", "Perceptual decisions involve accumulation of evidence (sensory signals) over time to a threshold, modelled as drift-diffusion (DDM). In monkeys, LIP area neurons accumulate motion evidence over time during random dot tasks (Shadlen). Value-based decisions involve OFC (encoding subjective value), vmPFC (comparative evaluation), and striatum (encoding expected reward). ACC monitors conflict and regulates response thresholds. PFC exerts top-down control over impulsive choices mediated by striatum and amygdala."),
    ("What is social neuroscience?", "Social neuroscience investigates the neural mechanisms underlying social cognition: face processing (fusiform face area, FFA -- right fusiform gyrus; superior temporal sulcus for gaze and motion); theory of mind (TPJ, mPFC, STS); empathy (ACC, anterior insula for pain empathy; mirror neuron-related areas for motor empathy); trust (oxytocin, amygdala modulation of approach behaviour); and moral cognition (vmPFC, TPJ, ACC)."),
    ("What is the fusiform face area?", "The FFA (fusiform face area, right fusiform gyrus) responds selectively to faces with greater activation than to non-face objects. It was identified by Kanwisher using fMRI (1997). The FFA is part of a distributed face-processing network: early visual processing (V1), holistic representation (OFA), dynamic face features (STS), and identity and expression (anterior temporal lobe). Prosopagnosia (face-blindness) can result from FFA lesions or developmental abnormality."),
    ("What is the neural basis of empathy?", "Empathy involves understanding and sharing others' affective and cognitive states. Affective empathy (feeling with others) activates the anterior insula and ACC -- regions involved in one's own pain and emotion. Cognitive empathy (mentalisation -- understanding what others feel) activates the TPJ, mPFC, and STS. The relative balance of these systems differs across individuals and in autism (reduced cognitive empathy) vs psychopathy (reduced affective empathy)."),
    ("What is the neuroscience of moral cognition?", "Moral cognition involves multiple neural systems: the vmPFC encodes the value of actions for self and others (damage causes 'utilitarian' decisions at personal cost -- Trolley problem); the TPJ supports perspective-taking and attributing intent to others' moral violations (essential for judging attempted harm); the ACC monitors moral conflict; and the amygdala generates emotional responses to moral violations. Psychopaths show amygdala and vmPFC hypoactivity during moral scenarios."),
    ("What is neuromodulation?", "Neuromodulation refers to the modification of neural activity by neuromodulators (dopamine, serotonin, acetylcholine, noradrenaline, histamine, and neuropeptides) that act via G protein-coupled receptors over slower timescales than ionotropic transmission. Neuromodulators regulate the gain of neural circuits, enabling flexible context-dependent processing. Clinical neuromodulation includes deep brain stimulation, TMS, tDCS, and pharmacological interventions targeting monoamine systems."),
    ("What is transcranial magnetic stimulation?", "TMS applies brief magnetic pulses through a coil placed on the scalp, inducing electric currents in superficial cortex. Single-pulse TMS reveals the timing of cortical contributions to behaviour; repetitive TMS (rTMS) produces lasting modulation (inhibitory at 1 Hz; facilitatory at 10 Hz). rTMS over the left DLPFC is an FDA-cleared treatment for major depressive disorder. TMS combined with EEG reveals cortical excitability and connectivity."),
    ("What is transcranial direct current stimulation?", "tDCS applies weak direct current (1-2 mA) through scalp electrodes, modulating cortical excitability without directly triggering action potentials. Anodal tDCS increases excitability (depolarises resting potential); cathodal decreases it. It modulates synaptic plasticity and has been studied for motor rehabilitation, cognitive enhancement, and treatment of depression and pain. Effects are modest and variable; optimal protocols are still being established."),
    ("What is deep brain stimulation?", "DBS involves implanting electrodes in specific brain targets, connected to a subcutaneous pulse generator, delivering continuous high-frequency stimulation. Targets: subthalamic nucleus or GPi for Parkinson's disease (effective for motor symptoms, approved globally); ventral intermediate thalamic nucleus for essential tremor; anterior thalamus for epilepsy; subcallosal cingulate (area 25) and nucleus accumbens for treatment-resistant depression. Mechanisms remain debated (does it activate or inhibit?)."),
    ("What is the neural basis of language?", "Language is processed in a distributed left-hemisphere network: Broca's area (BA44/45 -- production, syntax); Wernicke's area (BA22 -- comprehension); the arcuate fasciculus (dorsal stream -- phonological processing); and the anterior temporal lobe and uncinate fasciculus (ventral stream -- semantic and lexical processing). The dual-stream model (Hickok and Poeppel): dorsal stream for phonological-to-motor mapping; ventral stream for sound-to-meaning mapping."),
    ("What is the split-brain phenomenon?", "When the corpus callosum is severed (for epilepsy control), the two cerebral hemispheres can function somewhat independently. Sperry and Gazzaniga showed: information presented to the left visual field (processed by right hemisphere) cannot be verbally reported (language is left-hemisphere) but can be expressed by left-hand selection; the right hemisphere can recognise but not name objects. Split-brain research revealed hemispheric lateralisation of language, visuospatial skills, and emotional processing."),
    ("What is hemispheric asymmetry?", "The left hemisphere dominates language, analytic processing, positive emotion (approach), and fine-grained sequential processing. The right hemisphere dominates holistic processing, visuospatial skills, negative emotion (withdrawal), prosody, and face processing. Lateralisation is present from birth (auditory cortex asymmetry, hand preference). Damage to the left hemisphere causes aphasia; right hemisphere damage causes visuospatial neglect, prosodic impairment, and emotional dysregulation."),
    ("What is neural oscillations?", "Neural oscillations reflect rhythmic fluctuations in neural excitability arising from interacting excitatory and inhibitory networks. Theta oscillations (4-8 Hz) in hippocampus organise memory encoding and retrieval; gamma oscillations (30-80 Hz) reflect local excitatory-inhibitory balance and sensory binding; alpha oscillations (8-13 Hz) reflect cortical inhibition; beta (13-30 Hz) reflects motor and cognitive status quo. Cross-frequency coupling (theta-gamma) organises information in working memory."),
    ("What is grid cells and place cells?", "Place cells (O'Keefe, 1971) in hippocampal CA1 and CA3 fire when an animal occupies specific spatial locations ('place fields'), creating a cognitive map of the environment. Grid cells (Moser et al.) in entorhinal cortex fire in a hexagonal lattice pattern across the environment, providing a metric coordinate system. Head direction cells, border cells, and speed cells complement this system to form a comprehensive neural GPS. O'Keefe and the Mosers shared the 2014 Nobel Prize."),
    ("What is the medial temporal lobe memory system?", "The medial temporal lobe (MTL) memory system -- comprising the hippocampus, entorhinal cortex, perirhinal cortex, and parahippocampal cortex -- is essential for encoding and consolidating declarative (explicit) memories. The perirhinal cortex processes item familiarity; the hippocampus binds items into coherent episodes (recollection). Standard model: the hippocampus initially holds memories; slow sleep-dependent consolidation transfers representations to the neocortex for long-term storage."),
    ("What is synaptic tagging and capture?", "Synaptic tagging and capture (STC) explains how protein synthesis-dependent late LTP can be restricted to synapses that received specific stimulation. A 'tag' is set at stimulated synapses (by early LTP induction); proteins synthesised in the soma are 'captured' only at tagged synapses. This mechanism enables synapse-specific plasticity despite the need for new proteins synthesised in a shared cell body. It links early and late LTP to explain how synaptic specificity of memory encoding is maintained."),
    ("What is the dendritic computation?", "Dendrites are not passive conductors -- they are active computational elements. Dendrites contain voltage-gated channels (Na+, Ca2+, K+, Ih) that generate local dendritic spikes and back-propagating action potentials. Distal dendrites of pyramidal cells can perform independent computations (coincidence detection, non-linear integration). Dendritic spines are the biochemical compartments for individual synapses, isolating Ca2+ signals for synapse-specific plasticity."),
    ("What is oligodendrocyte function?", "Oligodendrocytes are the myelin-producing cells of the CNS (Schwann cells myelinate the PNS). Each oligodendrocyte myelinates multiple axonal segments (up to 40). Myelination dramatically increases conduction velocity and energy efficiency (saltatory conduction). Oligodendrocyte precursor cells (OPCs) are the most mitotically active cells in the adult brain and are a target for remyelination therapies in MS. Activity-dependent myelination adjusts circuit timing."),
    ("What is the enteric nervous system?", "The ENS (gut's 'second brain') is a network of ~500 million neurons embedded in the gut wall -- more neurons than the spinal cord. It controls gut motility, secretion, and blood flow independently of the CNS. Neurons include excitatory (ACh, substance P) and inhibitory (NO, VIP) motor neurons, as well as sensory neurons detecting gut distension and chemical content. The ENS communicates with the CNS via the vagus (gut-brain axis), influencing mood and cognition."),
    ("What is the neural basis of habit formation?", "Habits develop through repetition of goal-directed actions, which gradually shift control from the PFC (deliberate) to the dorsal striatum, specifically the dorsolateral striatum (habitual control) -- mediated by dopamine D2 receptor-expressing medium spiny neurons. Lesion of the dorsomedial striatum (goal-directed system) accelerates habit formation. Stimulus-response associations in habits are encoded by activity patterns in the striatum and are highly resistant to outcome devaluation."),
    ("What is the neural basis of fear conditioning?", "Classical fear conditioning (Pavlov, LeDoux) pairs a neutral CS (tone) with an aversive US (shock). The basolateral amygdala (BLA) is essential for acquiring fear -- it receives CS (via auditory thalamus and cortex) and US (via somatosensory cortex and PAG) and forms CS-US associations via NMDA-dependent LTP. The central amygdala drives fear expression (freezing via PAG, autonomic responses via hypothalamus). Extinction (CS without US) forms a new inhibitory memory, not erasure."),
    ("What is extinction learning?", "Extinction is the progressive reduction of a conditioned response when the CS is repeatedly presented without the US. It is not erasure of the original memory but formation of a new inhibitory memory (infralimbic PFC activates intercalated cells in the amygdala, inhibiting the central amygdala). Extinction is context-dependent -- returning to the conditioning context causes fear to spontaneously recover (renewal). Reconsolidation can be targeted to permanently reduce fear memories."),
    ("What is memory reconsolidation?", "When a consolidated memory is reactivated (recalled), it enters a labile state and must be reconsolidated. During this window, memories can be modified or weakened. Reconsolidation requires protein synthesis and NMDA receptor activation (like initial consolidation). Propranolol during recall of a traumatic memory can weaken its emotional valence (clinical trials for PTSD). Memory reconsolidation provides a window for targeted therapeutic intervention."),
    ("What is the orbitofrontal cortex function?", "The OFC encodes the current value of rewards and punishments, updating with outcome information. It is critical for reversal learning (switching to a new rewarded option when contingencies reverse) and expected value computations. OFC damage causes inability to update behaviour in response to changing reward contingencies and contributes to decision-making deficits in addiction and OCD. The OFC integrates sensory information with motivational state to encode flavour and subjective value."),
    ("What is the anterior cingulate cortex function?", "The ACC (cingulate gyrus anterior to the genu of the corpus callosum) has multiple functions: cognitive (dACC -- conflict monitoring, error detection, attention allocation), pain processing (midcingulate -- affective component of pain), and emotional regulation (sACC/area 25 -- depression target for DBS). The error-related negativity (ERN) ERP component reflects ACC activity after errors. Subgenual ACC (sgACC) activity is elevated in depression; DBS of sgACC or its white matter connections relieves treatment-resistant depression."),
    ("What is the insular cortex function?", "The insula (buried within the lateral sulcus) integrates interoceptive signals and is central to body awareness, emotion, and social cognition. The posterior insula processes primary interoceptive sensations (temperature, pain, visceral). The anterior insula integrates these with higher cognitive signals to produce subjective emotional feelings (Craig's theory of consciousness of emotions) and empathy. Insular damage impairs drug craving, pain unpleasantness, and emotional awareness."),
    ("What is the supplementary motor area?", "The SMA (supplementary motor area, medial frontal lobe, BA6) is active during planning and preparation of voluntary movements, particularly self-initiated actions and complex sequences. The Libet experiment showed SMA activity (readiness potential) precedes conscious awareness of intention to move by ~500 ms. The SMA also coordinates bimanual movements and is involved in procedural sequence learning. Adjacent preSMA is more cognitive; SMA proper is more motor."),
    ("What is the theta oscillation in memory?", "Hippocampal theta oscillations (4-8 Hz) are prominent during exploration and REM sleep. They organise sequential memory encoding: place cells fire at specific theta phases, with cells encoding different spatial locations firing at successively earlier phases ('theta sequences'). Theta organises gamma oscillations in working memory via nested theta-gamma coupling. Theta disruption (entorhinal inactivation) impairs spatial learning. Theta is generated by the medial septum acting as a pacemaker."),
    ("What is fast ripple oscillation in epilepsy?", "High-frequency oscillations (HFOs, >80 Hz) -- especially fast ripples (>250 Hz) -- recorded intracranially are biomarkers of epileptogenic tissue. They reflect bursts of synchronised action potentials in pathologically excitable neuronal populations. Fast ripples occur in seizure-onset zones and may be used to guide epilepsy surgery resection. They differ from physiological sharp wave ripples (80-140 Hz) in hippocampus during memory consolidation."),
    ("What is the default mode network and mental illness?", "DMN hyperactivity underlies ruminative thought in depression; hyperconnectivity of DMN with other networks in anxiety. In schizophrenia, DMN connectivity is disrupted, correlating with reality monitoring failures. Alzheimer's disease causes preferential amyloid deposition in DMN hubs (posterior cingulate, precuneus). In autism, DMN connectivity differs, correlating with social cognitive differences. Mindfulness meditation reduces DMN activity and rumination."),
    ("What is neuroimaging in clinical neuroscience?", "Clinical neuroimaging: CT (rapid assessment of haemorrhage, fractures); MRI (superior soft tissue detail -- structural, functional, diffusion, spectroscopy); PET (amyloid and tau imaging in Alzheimer's diagnosis -- florbetapir, flortaucipir; dopamine transporter imaging in Parkinson's); SPECT; and fMRI (presurgical language and motor mapping). Advanced techniques: ASL perfusion MRI, MR spectroscopy (NAA, choline, Cr), and ultra-high-field 7T MRI for hippocampal subfield resolution."),
    ("What is patch clamp electrophysiology?", "Patch clamp (Neher and Sakmann, Nobel 1991) uses a glass micropipette with a tight gigaohm seal on the cell membrane to record single-channel or whole-cell currents with picoampere resolution. Configurations: cell-attached (minimal disturbance), whole-cell (full access to intracellular), inside-out (intracellular face exposed), outside-out (extracellular face exposed). It revolutionised understanding of ion channels, synaptic transmission, and pharmacology of neural circuits."),
    ("What is calcium imaging?", "Calcium imaging uses genetically encoded calcium indicators (GECIs, e.g., GCaMP variants) or synthetic dyes to monitor intracellular Ca2+ as a proxy for neural activity. GCaMP is expressed via AAV viral vectors; two-photon microscopy provides cellular-resolution imaging in vivo in behaving animals. Large-scale calcium imaging (light-sheet, Neuropixels probes for electrophysiology) simultaneously records thousands of neurons across brain regions during behaviour."),
    ("What is single-unit recording?", "Single-unit recording uses sharp microelectrodes or tetrodes to record extracellular action potentials ('spikes') from individual neurons in vivo. Spike sorting (template matching, clustering) isolates the activity of individual units from multiunit recordings. High-density silicon probes (Neuropixels -- 960 channels in 1 cm) record hundreds of neurons simultaneously across cortical layers. Single-unit recording has revealed place cells, mirror neurons, and decision-related activity."),
    ("What is the Hodgkin-Huxley model?", "The Hodgkin-Huxley (HH) model (1952, Nobel 1963) is the first quantitative model of action potential generation based on voltage clamp recordings from squid giant axon. It describes Na+ and K+ conductances as functions of voltage and time using differential equations with gating variables (m, h for Na+; n for K+). The model accurately predicts action potential shape, threshold, refractory period, and propagation velocity. All modern computational neuron models descend from HH."),
    ("What is spike-timing-dependent plasticity?", "STDP is a form of Hebbian plasticity in which the precise timing of pre- and postsynaptic spikes determines the direction and magnitude of synaptic change. If the presynaptic spike precedes the postsynaptic spike by <20 ms, the synapse is potentiated (pre leads post -- causal, Hebbian). If post precedes pre, the synapse is depressed (anti-Hebbian). STDP provides a mechanism for learning temporal sequences and is implemented by NMDA receptors as coincidence detectors with asymmetric Ca2+ dynamics."),
    ("What is the central pattern generator?", "Central pattern generators (CPGs) are neural circuits in the spinal cord and brainstem that produce rhythmic motor output (walking, breathing, chewing) without requiring continuous sensory or supraspinal input. CPGs use half-centre oscillators -- mutually inhibiting neuron populations alternating activity to generate rhythmic flexor-extensor patterns. Locomotor CPGs in the lumbar spinal cord can be activated by epidural stimulation in people with spinal cord injury, enabling some voluntary movement."),
    ("What is neurogenesis in the adult hippocampus?", "New neurons are generated from neural stem cells in the subgranular zone of the dentate gyrus throughout adulthood. They mature over 4-6 weeks, receiving excitatory input during a period of hyperexcitability, and integrate into existing circuits. New neurons contribute to pattern separation (distinguishing similar experiences), contextual learning, and forgetting (replacing old memories). Exercise, enriched environments, and antidepressants increase hippocampal neurogenesis; chronic stress and aging decrease it."),
    ("What is neurofeedback?", "Neurofeedback provides real-time feedback of brain activity (EEG or fMRI) to enable individuals to learn to volitionally control their neural states. Applications: theta/alpha training for attention (ADHD treatment -- modest evidence); alpha training for anxiety; sensorimotor rhythm training for epilepsy (reducing seizure frequency); and real-time fMRI neurofeedback for chronic pain and depression (training vmPFC or amygdala activity). Effects are variable; rigorous sham-controlled studies show modest but real effects in some conditions."),
    ("What is neuroprosthetics?", "Neuroprosthetics interface with the nervous system to restore lost function. Examples: cochlear implants (stimulate auditory nerve, restore hearing); retinal implants (stimulate remaining retinal cells, restore rudimentary vision); brain-computer interfaces (BCI) -- Utah array or ECoG recordings from motor cortex to control robotic arms or cursor movements in paralysed patients; and spinal cord stimulation to restore standing and stepping after SCI (van den Berg and Courtine). Bidirectional BCIs also provide somatosensory feedback."),
    ("What is the neural basis of creativity?", "Creativity involves interactions among three large-scale networks: the DMN (spontaneous idea generation, associative thinking, mind-wandering); the executive control network (evaluation and refinement of ideas, maintaining goal relevance); and the salience network (switching between DMN and executive control based on relevance). Creative individuals show atypically high functional connectivity between DMN and executive control -- normally anti-correlated -- enabling simultaneous generation and evaluation of ideas."),
]

assert len(pairs) >= 100, f"Only {len(pairs)} pairs — need 200"

with OUT.open("w") as f:
    for q, a in pairs:
        f.write(json.dumps({"messages": [
            {"role": "user", "content": q},
            {"role": "assistant", "content": a}
        ]}) + "\n")

print(f"OK upgrade_l.jsonl -- {len(pairs)} premium neuroscience pairs written.")
